import{_ as r,o as i,c as s,a4 as a,j as t,a as o}from"./chunks/framework.BRzJ4ijD.js";const b=JSON.parse('{"title":"Back of Envelope 估算","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/estimation/back-of-envelope.md","filePath":"system-design/estimation/back-of-envelope.md","lastUpdated":1788475713000}'),l={name:"system-design/estimation/back-of-envelope.md"};function n(d,e,c,h,u,p){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="back-of-envelope-估算" tabindex="-1">Back of Envelope 估算 <a class="header-anchor" href="#back-of-envelope-估算" aria-label="Permalink to &quot;Back of Envelope 估算&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Back of Envelope (BOE) 估算</strong> 是 Jeff Dean / Google 内 部 docs 流行开来的&quot;贴式估算法&quot;——不写代码, 不查精确值, 用一些<strong>工作功率/带宽/缓存层次参考数字</strong> 在 1 分钟内得到 capex/opex/吞吐数量级。 它的核心是&quot;先估数量级, 再 cap 硬件清单&quot;, 而不是 &quot;build 后爆掉&quot;。 一套基础参考数 (latency numbers every programmer should know Brendan Gregg version) 让你立刻知道 1ms 内能做啥: SSD 查 4KB page &lt; DNS round trip &lt; 1 Gbps 网络, 那就是 cache 设计的根。 本章梳理 BOE 参考表, 给 8 个工业例题 + 公司 / 个人估算 思维模版, 指出<strong>最易估算错的几个</strong> (内存带宽、压缩比、多核比例), exercises。</p><hr><h2 id="一、基础参考数字" tabindex="-1">一、基础参考数字 <a class="header-anchor" href="#一、基础参考数字" aria-label="Permalink to &quot;一、基础参考数字&quot;">​</a></h2><h3 id="latency-numbers-every-programmer-should-know" tabindex="-1">Latency Numbers Every Programmer Should Know <a class="header-anchor" href="#latency-numbers-every-programmer-should-know" aria-label="Permalink to &quot;Latency Numbers Every Programmer Should Know&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>时间 (2026年数)</th><th>备注</th></tr></thead><tbody><tr><td>L1 cache hit</td><td>~1 ns</td><td>compute-bound kernel core within 1 cycle 锁</td></tr><tr><td>L2 cache hit</td><td>~3-4 ns</td><td>shared within one core&#39;s prefetch</td></tr><tr><td>L3 cache hit</td><td>~12 ns</td><td>shared across cores of same socket</td></tr><tr><td>RAM access (DRAM)</td><td>~100 ns</td><td>main memory random read</td></tr><tr><td>SSD 4KB 随机读</td><td>~150 µs (NVMe); ~100 µs (Intel Optane)</td><td>one 4KB page I/O</td></tr><tr><td>HDD 4KB 随机读</td><td>~10 ms (7200rpm)</td><td>seek + rotation</td></tr><tr><td>1Gbps 网络传 1MB</td><td>~10ms</td><td>LAN single link</td></tr><tr><td>25Gbps 网络传 1MB</td><td>~0.4ms</td><td>datacenter link</td></tr><tr><td>同城 DC RTT</td><td>~1-2ms</td><td>P50</td></tr><tr><td>跨美 RTT</td><td>~50-70ms</td><td>P50 沿光纤</td></tr><tr><td>跨洲 RTT</td><td>~150-250ms</td><td>P50</td></tr><tr><td>TXN 写 + fsync (NVMe)</td><td>~1-2ms</td><td>database commit</td></tr></tbody></table><h3 id="storage-costs" tabindex="-1">Storage Costs <a class="header-anchor" href="#storage-costs" aria-label="Permalink to &quot;Storage Costs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>介质</th><th>$/GB/月 (2026)</th></tr></thead><tbody><tr><td>NVMe SSD (云, gp3 ~$0.08/GB provisioned IOPS)</td><td>~$0.10</td></tr><tr><td>HDD (云, st1, Magnetic)</td><td>~$0.025</td></tr><tr><td>S3 standard</td><td>~$0.023</td></tr><tr><td>Glacier deep archive</td><td>~$0.00099</td></tr><tr><td>RAM (云实例 included)</td><td>~$10 (3000× SSD)</td></tr></tbody></table><p>node 上 1GB RAM 是 1GB SSD 的 ~100× cost. 决定 &quot;cached in memory vs spilled to disk&quot; trade-off。</p><h3 id="通过量数字" tabindex="-1">通过量数字 <a class="header-anchor" href="#通过量数字" aria-label="Permalink to &quot;通过量数字&quot;">​</a></h3><ul><li>单 Redis 实例: 100K QPS get/set 100B value。</li><li>单 Postgres 16 CPU: 30K 写 TPS (取决于 fsync)+ 100K 主键读 (cache hit)。</li><li>Kafka 单 broker: 200MB/s (1MB batch), 50k msg/s。</li><li>单 nginx worker: 100K req/s 静态资源。</li><li>RDMA/DPDK NIC: 100Gbps 充分能用 ~50Gbps user。</li></ul><h3 id="人的智力评估-不写-1b-qps" tabindex="-1">人的智力评估: 不写 1B QPS <a class="header-anchor" href="#人的智力评估-不写-1b-qps" aria-label="Permalink to &quot;人的智力评估: 不写 1B QPS&quot;">​</a></h3><p>当有人在白板上说&quot;业务量 100B QPS&quot;, 立刻判断不可能: 全球互联网骨干带宽 ~100 Tbps, 平均 request 1KB → 12.5 GB/s = 100 billion bytes/s = 100GB/s, 但中 国 全国骨干 1 PBps ≈ 1 思-构成 . <strong>总量级快速否决掉无意义需求</strong>。</p><hr><h2 id="二、8-个工业例题" tabindex="-1">二、8 个工业例题 <a class="header-anchor" href="#二、8-个工业例题" aria-label="Permalink to &quot;二、8 个工业例题&quot;">​</a></h2><h3 id="例1-1-million-dau-social-media-platform" tabindex="-1">例1: 1 million DAU social media platform <a class="header-anchor" href="#例1-1-million-dau-social-media-platform" aria-label="Permalink to &quot;例1: 1 million DAU social media platform&quot;">​</a></h3><p>输入: 1M DAU, 每用户 30 分钟浏览 feed, 每分钟 scroll 5 屏, 每屏 10 posts, 每 post 30 chars + 1 image 100KB.</p><p>Throughput estimate:</p><ul><li>daily scroll time = 1M × 30 = 30M minutes × 5 × 10 = 1,500M post views / day.</li><li>365 = 547.5B post-views/year (~17 reports/秒 average).</li><li>Peak hour rate: 30× avg → ~17×30 ≈ 510 RPS peak.</li></ul><p>Storage:</p><ul><li>1K posts/day/user × 1M × 30KB = 30GB/day, 11TB/year.</li></ul><p>Cache strategy:</p><ul><li>Hot 7-day data cache hot feed = 7 × 30 = 210GB in Redis; ≤1GB cache per dedicated Redis instance = 210 instances = 不实际.</li><li>Post content to S3 11TB/year × $0.023 = $5.7/month incremental.</li></ul><p>瓶颈 is not posts but feed images. CDN + thumbnail = cache hit 90%.</p><h3 id="例2-500k-active-concurrent-voip-buddy-pre-built" tabindex="-1">例2: 500K active concurrent VoIP-buddy pre-built <a class="header-anchor" href="#例2-500k-active-concurrent-voip-buddy-pre-built" aria-label="Permalink to &quot;例2: 500K active concurrent VoIP-buddy pre-built&quot;">​</a></h3><p>输入: 一个 5 人 call, 每人 2MBps 1080p video (1-way), mesh top.</p><ul><li>Total uplink = 5 users × 2 MBps = 10 MBps, full mesh 4 downlink / user (4 MBps total transmit per user) → 5 × 4 = 20 MBps total → 160 Mbps per call.</li><li>100K concurrent calls = 16 Tbps server relay media (SFU model) - 需要 ~160 个 server 100Gbps NICs.</li></ul><p>Mesh won&#39;t work at 5 users总带宽太重 → SFU (selective forwarding unit) routing. LiveKit/Jitsi 都这样.</p><h3 id="例3-银行账户-100k-tps" tabindex="-1">例3: 银行账户 100K TPS <a class="header-anchor" href="#例3-银行账户-100k-tps" aria-label="Permalink to &quot;例3: 银行账户 100K TPS&quot;">​</a></h3><ul><li>100K TXN/s insert/update to ACID database with fsync NVMe:</li><li>100K / 30K = 3.33x oversubscribed single Postgres → sharding by acctId 必需.</li><li>4 shards × 1 primary + 2 replicas each = 12 instances 16-core.</li><li>~$3K × 12 = $36K/month instance; storage capex 1TB × $0.10 / GB / month × 4 = $400/month.</li></ul><h3 id="例4-1b-iot-遥测-ingest" tabindex="-1">例4: 1B IoT 遥测 ingest <a class="header-anchor" href="#例4-1b-iot-遥测-ingest" aria-label="Permalink to &quot;例4: 1B IoT 遥测 ingest&quot;">​</a></h3><ul><li>1B devices × 100KB/day = 100TB/day ingest.</li><li>Kafka at 200MB/s/broker × 1 day = 17TB/broker/day → 100/17 = 6 brokers (we need ~ 7-8 brokers with replication).</li><li>Storage hot-30day: 3PB cold storage → S3 Glacier $0.00099/GB × 3M GB = $3K/month.</li></ul><h3 id="例5-1m-qps-product-detail-page" tabindex="-1">例5: 1M QPS product detail page <a class="header-anchor" href="#例5-1m-qps-product-detail-page" aria-label="Permalink to &quot;例5: 1M QPS product detail page&quot;">​</a></h3><ul><li>1M QPS, response ~5KB.</li><li>Egress = 5 GB/s = 40Gbps — 需要 ~40-50 × CDN edge nodes at 1 Gbps each.</li><li>Most cached 90% = 900K QPS from CDN; 100K back to origin = 5 GB/s divide microservices.</li><li>DB read 100K/s = 16-core Postgres ×4 with read replicas + cache layer.</li></ul><h3 id="例6-email-系统-1b-users" tabindex="-1">例6: Email 系统 1B users <a class="header-anchor" href="#例6-email-系统-1b-users" aria-label="Permalink to &quot;例6: Email 系统 1B users&quot;">​</a></h3><p>NOT feasible: world internet users ~5B. So 1B users plausible.</p><ul><li>1B users × 500 emails/month = 500B email/month = 16.6B emails/day = 200K emails/sec.</li><li>单 SMTP server ~500 emails/sec → 400 servers just for SMTP receiving. Storage 50GB/user × 1B = 50EB storage - S3 Glacier maybe $50M/month. Not practical.</li></ul><p>实际 webmail 1B users selectively delete + hot tier compressed only 1GB/user.</p><h3 id="例7-mapreduce-spark-1pb-数据-day" tabindex="-1">例7: MapReduce / Spark 1PB 数据 day <a class="header-anchor" href="#例7-mapreduce-spark-1pb-数据-day" aria-label="Permalink to &quot;例7: MapReduce / Spark 1PB 数据 day&quot;">​</a></h3><ul><li>100 nodes × 1Gbps = 100TB/day linear scalability.</li><li>For 1PB/day → need 10× = 1000 nodes minimum. Cost per node $3/h × 24h × 1000 × 30 days = $2.16M/month.</li></ul><p>实际 Spark/Databricks 提供自动 spot pricing 折扣.</p><h3 id="例8-1m-qps-social-network-timeline-排序-频-率熵的" tabindex="-1">例8: 1M QPS social-network Timeline 排序 频 率熵的 <a class="header-anchor" href="#例8-1m-qps-social-network-timeline-排序-频-率熵的" aria-label="Permalink to &quot;例8: 1M QPS social-network Timeline 排序 频 率熵的&quot;">​</a></h3><ul><li>1M QPS × 100ms rank (cached 99% because social media hot user fanout architecture).</li><li>1% cache miss = 10K actual ranking hits DB / backend ranking service.</li><li>Dragon-style score ranking service at 10K/s with model inference (8-core GPU) → 10 × 8-GPU = 80 GPUs.</li></ul><hr><h2 id="三、易错点" tabindex="-1">三、易错点 <a class="header-anchor" href="#三、易错点" aria-label="Permalink to &quot;三、易错点&quot;">​</a></h2><h3 id="_1-缓存层是-memory-1000×-cost-of-ssd" tabindex="-1">1: 缓存层是 memory @1000× cost of SSD <a class="header-anchor" href="#_1-缓存层是-memory-1000×-cost-of-ssd" aria-label="Permalink to &quot;1: 缓存层是 memory @1000× cost of SSD&quot;">​</a></h3><p>不是想&quot;add Redis 减压 DB&quot;, 而要先算 cache 命中率与 capex.</p><h3 id="_2-数据库的-fsync-是-sequential-几乎-wall-clock-bound" tabindex="-1">2: 数据库的 fsync 是 sequential 几乎 wall-clock bound <a class="header-anchor" href="#_2-数据库的-fsync-是-sequential-几乎-wall-clock-bound" aria-label="Permalink to &quot;2: 数据库的 fsync 是 sequential 几乎 wall-clock bound&quot;">​</a></h3><p>PostgreSQL 在 NVMe 上 30K 写 TPS (1ms fsync time serial) regardless of cores. 不能 &quot;加几个 core&quot; 翻倍. 必分片。</p><h3 id="_3-带宽与突发" tabindex="-1">3: 带宽与突发 <a class="header-anchor" href="#_3-带宽与突发" aria-label="Permalink to &quot;3: 带宽与突发&quot;">​</a></h3><p>1Gbps WAN port 是满 100MB/s, 但 BDP (bandwidth-delay product) for 70ms transcontinental link = 100MB × 70ms / 8 (1Gb / 8MB) ≈ 8.75MB &quot;in flight buffer&quot;; saturate 必须 windowing.</p><h3 id="_4-gw-跨区-⇒-rtt-不在你控制" tabindex="-1">4: GW 跨区 ⇒ RTT 不在你控制 <a class="header-anchor" href="#_4-gw-跨区-⇒-rtt-不在你控制" aria-label="Permalink to &quot;4: GW 跨区 ⇒ RTT 不在你控制&quot;">​</a></h3><p>跨美 RTT 即 80ms. 想在 followup 内完成就是 fail-over 才行. 进入 multi-region 必须 数据异步复制.</p><h3 id="_5-number-skew-在极端-cluster-不-linear" tabindex="-1">5: Number skew 在极端 cluster 不 linear <a class="header-anchor" href="#_5-number-skew-在极端-cluster-不-linear" aria-label="Permalink to &quot;5: Number skew 在极端 cluster 不 linear&quot;">​</a></h3><p>要么 Amdahl 负载分布限制 50% scale ceiling, 要么 long tail latency tail P99 远超-datadog / 不平 arrierianment.</p>',56),t("h3",{估算:"",id:"_6-内存使用-vs-cache",tabindex:"-1"},[o("6: 内存使用 vs cache "),t("a",{class:"header-anchor",href:"#_6-内存使用-vs-cache","aria-label":'Permalink to "6: 内存使用 vs cache  {估算}"'},"​")],-1),a('<p>OSS 用 Redis cache, 不等于 1TB memory = 1TB cache for free. 突发 cache write 涨 OSS heap 80% induced eviction not subsample.</p><hr><h2 id="四、典型事故" tabindex="-1">四、典型事故 <a class="header-anchor" href="#四、典型事故" aria-label="Permalink to &quot;四、典型事故&quot;">​</a></h2><h3 id="twitter-2010-fail-whale" tabindex="-1">Twitter 2010 Fail Whale <a class="header-anchor" href="#twitter-2010-fail-whale" aria-label="Permalink to &quot;Twitter 2010 Fail Whale&quot;">​</a></h3><ul><li>Kestrel queue 笑 HA videos match pip estimation scalability missing hit data put processing singleton 2 000 错 看 ha 实际 use 额.</li><li>Fix: Redis hot use BOE real sharded partition cap (Migration to Manhattan + Redis + memcached.).</li></ul><h3 id="apple-card-launch-2019-拇-指-较-少" tabindex="-1">Apple Card launch 2019 拇 指 较 少 <a class="header-anchor" href="#apple-card-launch-2019-拇-指-较-少" aria-label="Permalink to &quot;Apple Card launch 2019 拇 指 较 少&quot;">​</a></h3><p>queue delay pre-launch BOE wrong pin jump 10× load peppercorns vs predicted瞬 financepe GDP 实Be 一 verification DB connection pool 实 explained.</p><ul><li>Fix: 立即 add 10× read replicas + Golding HBase circumvent relational Connection tests.</li></ul><h3 id="uicolored-with-compute-resources-500-users-best-case-10k-worst-case" tabindex="-1">UIColored with compute resources: 500 users best case, 10K worst case <a class="header-anchor" href="#uicolored-with-compute-resources-500-users-best-case-10k-worst-case" aria-label="Permalink to &quot;UIColored with compute resources: 500 users best case, 10K worst case&quot;">​</a></h3><p>SaaS startup 测试 100 users staging → production scaling 50 → 1 万 worst case 5× 胜 ince burn rate.</p><hr><h2 id="五、练习题" tabindex="-1">五、练习题 <a class="header-anchor" href="#五、练习题" aria-label="Permalink to &quot;五、练习题&quot;">​</a></h2><ol><li><strong>1 million DAU chat system</strong>, 平均每 user 100 messages / day, 每天 active 6 hours, peak factor 5×. 网络 QPS / DB 写 QPS / 持久化 storage / day.</li><li><strong>10 million DAU 电商</strong>, 平均每 user浏览 50 pages/day, 每页 20 product thumbnails cached 95%. 回源 QPS, 带 宽产.</li><li><strong>Slack 10K concurrent active users</strong> in 1 workspace, 平均 message 1KB 单条 4 messages/min/person. 网络与 WS-side throughput.</li><li><strong>720p live video Streaming platform 1M co-current watchers</strong>, 单 streamer. 出口带宽 &amp; server count for SFU routing.</li><li><strong>Walk: Estimate iPhone storage</strong>: user avg 20 apps × 100MB + 500 camera photos × 5MB + 200 videos × 50MB = 13GB+:</li></ol><hr><h2 id="六、易错清单" tabindex="-1">六、易错清单 <a class="header-anchor" href="#六、易错清单" aria-label="Permalink to &quot;六、易错清单&quot;">​</a></h2><ol><li><strong>fsync 是 sequential, 不是 parallel</strong>: 一个 disk fsync bulk 1ms. 不要 nest 同 sequential ramp.</li><li><strong>NIC bandwidth is symmetric</strong> but cloud 公網 提供 burst 但不 sustained: 100Gbps 利 fillshop Almost不合ed-配mir 频.</li><li><strong>Cloud pricing reads vs writes</strong> can be 10× different: S3 PUT vs GET count 异 步 price diff. 月 1B PUTs = $5K.</li><li><strong>CDN cost is per GB egress 不是 QPS</strong>: Hot CDN 50TB/month = $0.05/GB × 50T = $2.5K (CloudFront).</li><li><strong>Latency budget by user &lt; 100ms 限所有 hops</strong>: CDN edge 5ms + API 50ms + DB 查询 20ms 总 budget 不能超过 100ms real user P95.</li><li><strong>Cache hit ratio optimization is exponential rewards</strong>: <ul><li>50% cache hit → origin load 50%.</li><li>90% cache hit → origin load 10%.</li><li>99% cache hit → origin load 1%. add 9% hit ratio cuts origin load 10×; Jacobian divergence.</li></ul></li></ol><hr><h2 id="七、这一章带走的东西" tabindex="-1">七、这一章带走的东西 <a class="header-anchor" href="#七、这一章带走的东西" aria-label="Permalink to &quot;七、这一章带走的东西&quot;">​</a></h2><ol><li>Back-of-Envelope 让您在 5 分钟内拉白板 +钢结构 cap 业务量.</li><li>Latency numbers 提供首要 reference (L1 ns / L2 3-4 ns / DRAM 100 ns / NVMe 4KB 100µs / 同城 RTT 1-2ms / transcontinental 60ms) 让您 tragen 时快 比 唇某 brute tested wonder.</li><li>fsync 是 sequential ~1ms: 不能伸缩 by cores. must shard.</li><li>Spark/Kafka 1PB/day ~= 1000 nodes + $2M/month. Not trivial. 看 boss.</li><li>Cache hit ratio small gains scale exponentially → &quot;add cache then optimize hit ratio before backend scale&quot;.</li><li>CDN egress + GitHub Action dependencies 多 storage v 陨 cost infra cross razor always sebastopol consider Latencygenerator 整 布局.</li></ol><hr><p>下一节 → <a href="./littles-law">Little&#39;s Law</a></p>',21)])])}const g=r(l,[["render",n]]);export{b as __pageData,g as default};
